def solve():
    s = input()
    if any(c.isalpha() for c in s):
        # Change case of letters
        result = []
        for c in s:
            if c.isalpha():
                if c.islower():
                    result.append(c.upper())
                else:
                    result.append(c.lower())
            else:
                result.append(c)
        print("".join(result))
    else:
        # Reverse the string if no letters
        print(s[::-1])
